// Some portions generated by Co-Pilot
import React from "react";
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import Members from "../page";

describe("Members page", () => {
  it("renders correctly", () => {
    const { container } = render(<Members />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("does not mention removed members in the page copy", () => {
    render(<Members />);

    expect(
      screen.getAllByText(
        "Collaborate with leading Java vendors like Microsoft, Red Hat, IBM, and Alibaba.",
      ),
    ).not.toHaveLength(0);
    expect(screen.queryByText(/Google/)).not.toBeInTheDocument();
    expect(screen.queryByText(/Rivos/)).not.toBeInTheDocument();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<Members />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("has one primary heading and preserves membership navigation and tier pricing", () => {
    const { container } = render(<Members />);
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
    expect(
      screen.getByRole("heading", {
        level: 1,
        name: "Join the Adoptium® Working Group",
      }),
    ).toBeVisible();
    expect(screen.getByRole("link", { name: "Join Us" })).toHaveAttribute(
      "href",
      "/join",
    );
    expect(
      screen.getByRole("link", { name: "Become a Member" }),
    ).toHaveAttribute("href", "/join");
    expect(screen.getByRole("link", { name: "Our Members" })).toHaveAttribute(
      "href",
      "#strategic-sec",
    );
    for (const id of ["strategic-sec", "enterprise-sec", "participant-sec"])
      expect(container.querySelector(`#${id}`)).toBeInTheDocument();
    for (const price of [
      "€9,000 - €45,000",
      "€6,500 - €30,000",
      "€0 - €12,500",
    ])
      expect(screen.getByText(price)).toBeVisible();
    expect(container.querySelector("a button")).not.toBeInTheDocument();
  });

  it("preserves member logos and makes the full card accessible", () => {
    render(<Members />);
    expect(screen.getByRole("link", { name: "Microsoft" })).toHaveAttribute(
      "href",
      "https://opensource.microsoft.com",
    );
    expect(screen.getByRole("link", { name: "Red Hat" })).toHaveAttribute(
      "href",
      "https://www.redhat.com",
    );
    expect(screen.getByRole("link", { name: "Open Elements" })).toHaveAttribute(
      "href",
      "https://open-elements.com",
    );
  });
});
